"""Offline QA only: inspect real generated bytes, never mutate sources."""
from io import BytesIO
from pathlib import Path
import json
import re
import unicodedata
import fitz
from docx import Document
from web import kp2027_bm_rpt_aligned as bm

def norm(s):
    s=unicodedata.normalize("NFC",s)
    return " ".join(s.split())

def main():
    issues=[]
    checked=0
    for group,count in bm.COUNTS.items():
        for n in range(1,count+1):
            try:
                r=bm.lesson(group,n)
                w=Document(BytesIO(bm.render(group,n,"word")))
                head=w.tables[0].rows[0].cells
                assert "Kelas:" in head[0].text and "BAHASA MELAYU SK" in head[1].text
                # Read XML once, so merged cells are not repeated.
                from docx.oxml.ns import qn
                word=norm(" ".join(node.text or "" for node in w.element.iter(qn("w:t"))))
                with fitz.open(stream=bm.render(group,n,"pdf"),filetype="pdf") as d:
                    assert len(d)>=1
                    for p in d:
                        assert abs(p.rect.width-595.28)<2 and abs(p.rect.height-841.89)<2
                    teacher=d[0].search_for("Kelas:")
                    subject=d[0].search_for("BAHASA MELAYU SK")
                    assert teacher and subject and teacher[0].x0<subject[0].x0
                    pdf=norm(" ".join(p.get_text() for p in d))
                for fmt,txt in (("word",word),("pdf",pdf)):
                    for value in (r["sk_code"]+" "+r["sk"],r["sp_code"]+" "+r["sp"],r["objective"],r["criteria"],r["induction"],*r["activities"],r["pbd"],r["closure"],r["remedial"],r["extension"],"Refleksi"):
                        assert norm(value) in txt, fmt+": missing "+value
                    assert not re.search(r"\b(?:Kumpulan [AB]|(?:Lesson|PdP)\s*[:#]?\s*\d+)\b",txt,re.I),fmt+": printed internal ID"
                    assert "Refleksi (Auto" not in txt
                checked+=1
            except Exception as exc:
                issues.append({"group":group,"lesson":n,"error":str(exc)})
    report={"scope":"BM KP2027 ordinary Word/PDF","total":sum(bm.COUNTS.values()),"passed":checked,"issues":issues,"release":False}
    Path("qa_bm_ordinary_report.json").write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding="utf-8")
    print(json.dumps(report,ensure_ascii=False))
    if issues:raise SystemExit(1)

if __name__=="__main__":main()
